"""Streaming JSONL dataset intake, validation, duplicate detection, and canonical fingerprinting."""

from __future__ import annotations

import json
from collections.abc import Callable, Iterable, Iterator, Mapping
from pathlib import Path
from typing import Any

from pydantic import BaseModel, ConfigDict, ValidationError

from evalforge_maestro._canonical import StreamingCanonicalHasher
from evalforge_maestro.exceptions import (
    DatasetError,
    DuplicateCaseIdError,
    EmptyDatasetError,
)
from evalforge_maestro.types import EvaluationCase


class DatasetStreamResult(BaseModel):
    """Canonical metadata and SHA-256 fingerprint emitted at completion of dataset streaming."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    dataset_id: str
    dataset_version: str | None
    dataset_fingerprint: str
    evaluated_case_count: int
    dataset_capped: bool
    max_dataset_cases: int | None


class DatasetEngine:
    """Lazy streaming dataset loader enforcing schema contracts and canonical SHA-256 hashing."""

    def __init__(
        self,
        source: Path | str | Iterable[EvaluationCase | Mapping[str, Any]],
        *,
        dataset_id: str | None = None,
        dataset_version: str | None = None,
    ) -> None:
        if dataset_id is not None:
            cleaned_id = dataset_id.strip()
            if not cleaned_id:
                raise DatasetError("dataset_id must be a non-empty string", field="dataset_id")
            resolved_id = cleaned_id
        elif isinstance(source, (Path, str)):
            stem = Path(source).stem.strip()
            resolved_id = stem or "dataset"
        else:
            resolved_id = "in-memory"

        self._source: Path | str | Iterable[EvaluationCase | Mapping[str, Any]] = source
        self._dataset_id = resolved_id
        self._dataset_version = dataset_version

    @property
    def dataset_id(self) -> str:
        """Return resolved logical dataset identifier."""
        return self._dataset_id

    @property
    def dataset_version(self) -> str | None:
        """Return optional dataset version string."""
        return self._dataset_version

    def _iter_source_items(self) -> Iterator[tuple[int, Any, bool]]:
        """Yield (line_or_index, raw_item, is_unparsed_json_str) lazily."""
        if isinstance(self._source, (Path, str)):
            path = Path(self._source)
            if not path.is_file():
                raise DatasetError(f"Dataset file not found: {path}")
            try:
                with path.open("r", encoding="utf-8") as handle:
                    for line_no, raw_line in enumerate(handle, start=1):
                        stripped = raw_line.strip()
                        if not stripped:
                            continue
                        yield line_no, stripped, True
            except OSError as exc:
                raise DatasetError(f"Failed reading dataset file {path}: {exc}") from exc
            return

        for idx, item in enumerate(self._source, start=1):
            yield idx, item, False

    @staticmethod
    def _validate_item(line_no: int, raw_item: Any, *, is_json_line: bool) -> EvaluationCase:
        if is_json_line:
            try:
                parsed = json.loads(raw_item)
            except json.JSONDecodeError as exc:
                raise DatasetError(
                    f"Invalid JSON at line {line_no}: {exc.msg}",
                    line_number=line_no,
                ) from exc
            if not isinstance(parsed, dict):
                raise DatasetError(
                    f"Dataset line {line_no} must decode to a JSON object",
                    line_number=line_no,
                )
            raw_obj: Any = parsed
        elif isinstance(raw_item, EvaluationCase):
            # Re-validate via model_validate only if needed; preserve strictness cheaply
            return raw_item
        elif isinstance(raw_item, Mapping):
            raw_obj = dict(raw_item)
        else:
            raise DatasetError(
                f"Dataset record {line_no} must be EvaluationCase or Mapping",
                line_number=line_no,
            )

        raw_id = raw_obj.get("id")
        candidate_id = raw_id.strip() if isinstance(raw_id, str) and raw_id.strip() else None
        try:
            return EvaluationCase.model_validate(raw_obj)
        except ValidationError as exc:
            first_error = exc.errors()[0]
            loc = ".".join(str(part) for part in first_error.get("loc", ())) or None
            raise DatasetError(
                f"Schema validation failed at record {line_no}"
                f"{f' (case {candidate_id!r})' if candidate_id else ''}: {first_error['msg']}",
                line_number=line_no,
                case_id=candidate_id,
                field=loc,
            ) from exc

    def iter_cases(
        self,
        *,
        max_cases: int | None = None,
        on_complete: Callable[[DatasetStreamResult], None] | None = None,
    ) -> Iterator[EvaluationCase]:
        """Stream validated EvaluationCase objects while enforcing uniqueness and SHA-256 hashing."""
        if max_cases is not None and max_cases < 1:
            raise DatasetError("max_cases must be >= 1", field="max_cases")

        seen_ids: set[str] = set()
        hasher = StreamingCanonicalHasher()
        capped = False

        for line_no, raw_item, is_json_line in self._iter_source_items():
            if max_cases is not None and hasher.count >= max_cases:
                # 1-line non-blank lookahead confirmed additional unread records exist before EOF
                capped = True
                break

            case = self._validate_item(line_no, raw_item, is_json_line=is_json_line)
            if case.id in seen_ids:
                raise DuplicateCaseIdError(
                    f"Duplicate EvaluationCase.id {case.id!r} at record {line_no}",
                    line_number=line_no,
                    case_id=case.id,
                    field="id",
                )
            seen_ids.add(case.id)
            hasher.update(case.model_dump(mode="json"))
            yield case

        if hasher.count == 0:
            raise EmptyDatasetError("Dataset contains zero valid EvaluationCase records")

        result = DatasetStreamResult(
            dataset_id=self._dataset_id,
            dataset_version=self._dataset_version,
            dataset_fingerprint=hasher.hexdigest(),
            evaluated_case_count=hasher.count,
            dataset_capped=capped,
            max_dataset_cases=max_cases,
        )
        if on_complete is not None:
            on_complete(result)

    def fingerprint(self, *, max_cases: int | None = None) -> DatasetStreamResult:
        """Stream through the dataset and return canonical DatasetStreamResult metadata."""
        captured: list[DatasetStreamResult] = []
        for _ in self.iter_cases(max_cases=max_cases, on_complete=captured.append):
            pass
        return captured[0]

"""Generic synchronous and asynchronous Python callable adapter."""

from __future__ import annotations

import asyncio
import inspect
import time
from collections.abc import Callable, Mapping
from typing import Any

from pydantic import ValidationError

from evalforge_maestro._canonical import canonical_sha256, redact_secrets, round_score
from evalforge_maestro.exceptions import AdapterError
from evalforge_maestro.types import EvaluationCase, ExecutionResult


class CallableAdapter:
    """Adapter wrapping synchronous or asynchronous Python callables as TargetAdapter."""

    def __init__(
        self,
        fn: Callable[..., Any],
        *,
        system_version: str | None = None,
        model_id: str | None = None,
        config: Mapping[str, Any] | None = None,
        pass_case: bool = False,
        input_mapper: Callable[[EvaluationCase], Any] | None = None,
    ) -> None:
        if not callable(fn):
            raise AdapterError("CallableAdapter requires a callable target")
        if pass_case and input_mapper is not None:
            raise AdapterError("Cannot specify both pass_case=True and input_mapper")

        self._fn = fn
        self._system_version = system_version
        self._model_id = model_id
        self._pass_case = pass_case
        self._input_mapper = input_mapper
        self._is_coro_fn = inspect.iscoroutinefunction(fn) or inspect.iscoroutinefunction(
            getattr(fn, "__call__", None)
        )

        if config is not None:
            redacted = redact_secrets(dict(config))
            self._config_fingerprint: str | None = canonical_sha256(redacted)
            self._adapter_metadata: dict[str, Any] = {"config": redacted}
        else:
            self._config_fingerprint = None
            self._adapter_metadata = {}

    @property
    def system_version(self) -> str | None:
        """Return declared target system version."""
        return self._system_version

    @property
    def model_id(self) -> str | None:
        """Return declared target model identifier."""
        return self._model_id

    @property
    def config_fingerprint(self) -> str | None:
        """Return canonical SHA-256 fingerprint of redacted adapter configuration."""
        return self._config_fingerprint

    def _build_target_arg(self, case: EvaluationCase) -> Any:
        if self._input_mapper is not None:
            return self._input_mapper(case)
        if self._pass_case:
            return case
        return case.input

    async def execute(self, case: EvaluationCase) -> ExecutionResult:
        """Invoke the wrapped callable and return a validated ExecutionResult."""
        arg = self._build_target_arg(case)
        errors: list[str] = []
        output: Any = None
        start = time.perf_counter()

        try:
            if self._is_coro_fn:
                raw_out = await self._fn(arg)
            else:
                raw_out = await asyncio.to_thread(self._fn, arg)
                if inspect.isawaitable(raw_out):
                    raw_out = await raw_out
            output = raw_out
        except Exception as exc:
            errors.append(f"{type(exc).__name__}: {exc}")

        elapsed = round_score(max(0.0, time.perf_counter() - start))

        try:
            return ExecutionResult(
                case_id=case.id,
                input=case.input,
                output=output,
                elapsed_seconds=elapsed,
                errors=errors,
                system_version=self._system_version,
                model_id=self._model_id,
                config_fingerprint=self._config_fingerprint,
                adapter_metadata=dict(self._adapter_metadata),
            )
        except ValidationError as exc:
            return ExecutionResult(
                case_id=case.id,
                input=case.input,
                output=None,
                elapsed_seconds=elapsed,
                errors=[f"SerializationError: target output is not JSON-serializable ({exc})"],
                system_version=self._system_version,
                model_id=self._model_id,
                config_fingerprint=self._config_fingerprint,
                adapter_metadata=dict(self._adapter_metadata),
            )

"""Bounded-concurrency, fault-isolated evaluation orchestrator."""

from __future__ import annotations

import asyncio
import logging
import sys
import time
import uuid
from collections.abc import Sequence
from datetime import datetime, timezone
from importlib.metadata import PackageNotFoundError, version
from pathlib import Path
from typing import Any

from evalforge_maestro._canonical import canonical_json_str, round_score
from evalforge_maestro.datasets import DatasetEngine, DatasetStreamResult
from evalforge_maestro.exceptions import ExecutionError, MemoryLimitExceededError
from evalforge_maestro.types import (
    AggregateMetricSummary,
    CaseEvaluationRecord,
    EvaluationCase,
    ExecutionResult,
    Metric,
    MetricResult,
    MetricStatus,
    OrchestratorConfig,
    RetrievedChunk,
    RunRecord,
    TargetAdapter,
)

logger = logging.getLogger(__name__)


def _package_version() -> str:
    try:
        return version("evalforge-maestro")
    except PackageNotFoundError:  # pragma: no cover - uninstalled source fallback
        return "0.1.0.dev0"


def _get_resident_memory_mb() -> float | None:
    """Return current process peak RSS in MiB on POSIX, or None if unsupported."""
    try:
        import resource
    except ImportError:  # pragma: no cover - Windows lacks stdlib resource
        return None
    usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    if sys.platform == "darwin":  # pragma: no cover - macOS reports bytes
        return usage / (1024.0 * 1024.0)
    return usage / 1024.0


def _truncate_text(text: str, max_chars: int) -> tuple[str, bool]:
    if len(text) <= max_chars:
        return text, False
    return text[:max_chars], True


def _truncate_execution_result(
    execution: ExecutionResult,
    max_chars: int | None,
) -> ExecutionResult:
    """Truncate oversized output/context fields post-scoring without mutating active input."""
    if max_chars is None:
        return execution

    was_truncated = execution.truncated
    updates: dict[str, Any] = {}

    if isinstance(execution.output, str):
        trimmed, did_trim = _truncate_text(execution.output, max_chars)
        if did_trim:
            updates["output"] = trimmed
            was_truncated = True
    elif execution.output is not None:
        serialized = canonical_json_str(execution.output)
        if len(serialized) > max_chars:
            updates["output"] = serialized[:max_chars]
            was_truncated = True

    if execution.retrieved_chunks:
        new_chunks: list[RetrievedChunk] = []
        chunks_changed = False
        for chunk in execution.retrieved_chunks:
            trimmed_chunk_text, did_trim = _truncate_text(chunk.text, max_chars)
            if did_trim:
                chunks_changed = True
                was_truncated = True
                new_chunks.append(chunk.model_copy(update={"text": trimmed_chunk_text}))
            else:
                new_chunks.append(chunk)
        if chunks_changed:
            updates["retrieved_chunks"] = new_chunks

    if execution.errors:
        new_errors = [err[:max_chars] for err in execution.errors]
        if new_errors != execution.errors:
            updates["errors"] = new_errors
            was_truncated = True

    if execution.warnings:
        new_warnings = [warn[:max_chars] for warn in execution.warnings]
        if new_warnings != execution.warnings:
            updates["warnings"] = new_warnings
            was_truncated = True

    if not updates and was_truncated == execution.truncated:
        return execution

    updates["truncated"] = was_truncated
    return execution.model_copy(update=updates)


def _evaluate_metrics_safe(
    case: EvaluationCase,
    execution: ExecutionResult,
    metrics: Sequence[Metric],
) -> dict[str, MetricResult]:
    results: dict[str, MetricResult] = {}
    for metric in metrics:
        meta = metric.metadata
        try:
            outcome = metric.evaluate(case, execution)
        except Exception as exc:
            outcome = MetricResult(
                metric_id=meta.metric_id,
                metric_version=meta.metric_version,
                score=None,
                status=MetricStatus.INCONCLUSIVE,
                explanation=f"Metric evaluation error: {type(exc).__name__}: {exc}",
            )
        results[outcome.metric_id] = outcome
    return results


def _build_aggregates(
    metrics: Sequence[Metric],
    records: Sequence[CaseEvaluationRecord],
) -> tuple[dict[str, AggregateMetricSummary], dict[MetricStatus, int], list[str]]:
    global_counts: dict[MetricStatus, int] = {status: 0 for status in MetricStatus}
    per_metric_scores: dict[str, list[float]] = {m.metadata.metric_id: [] for m in metrics}
    per_metric_counts: dict[str, dict[MetricStatus, int]] = {
        m.metadata.metric_id: {status: 0 for status in MetricStatus} for m in metrics
    }
    metric_versions = {m.metadata.metric_id: m.metadata.metric_version for m in metrics}
    mandatory_failed: list[str] = []

    for rec in records:
        case_failed_or_errored = bool(rec.execution.errors)
        for metric_id, m_res in rec.metrics.items():
            global_counts[m_res.status] += 1
            if metric_id not in per_metric_counts:
                per_metric_counts[metric_id] = {status: 0 for status in MetricStatus}
                per_metric_scores[metric_id] = []
                metric_versions[metric_id] = m_res.metric_version
            per_metric_counts[metric_id][m_res.status] += 1
            if m_res.status != MetricStatus.NOT_APPLICABLE and m_res.score is not None:
                per_metric_scores[metric_id].append(m_res.score)
            if m_res.status in (MetricStatus.FAIL, MetricStatus.INCONCLUSIVE):
                case_failed_or_errored = True
        if rec.mandatory and case_failed_or_errored:
            mandatory_failed.append(rec.case_id)

    aggregates: dict[str, AggregateMetricSummary] = {}
    for metric_id, counts in per_metric_counts.items():
        scores = per_metric_scores[metric_id]
        mean = round_score(sum(scores) / len(scores)) if scores else None
        aggregates[metric_id] = AggregateMetricSummary(
            metric_id=metric_id,
            metric_version=metric_versions[metric_id],
            mean_score=mean,
            applicable_count=len(scores),
            pass_count=counts[MetricStatus.PASS],
            fail_count=counts[MetricStatus.FAIL],
            warning_count=counts[MetricStatus.WARNING],
            inconclusive_count=counts[MetricStatus.INCONCLUSIVE],
            not_applicable_count=counts[MetricStatus.NOT_APPLICABLE],
        )

    return aggregates, global_counts, sorted(mandatory_failed)


class EvaluationOrchestrator:
    """Coordinates bounded-concurrency target execution, scoring, and run assembly."""

    def __init__(
        self,
        *,
        config: OrchestratorConfig | None = None,
        storage_root: Path | str | None = None,
    ) -> None:
        self._config = config or OrchestratorConfig()
        self._storage_root = Path(storage_root) if storage_root is not None else Path(".evalforge")

    @property
    def config(self) -> OrchestratorConfig:
        """Return active orchestrator configuration."""
        return self._config

    @property
    def storage_root(self) -> Path:
        """Return configured artifact root directory."""
        return self._storage_root

    def _check_memory_guardrail(self) -> None:
        max_mb = self._config.max_memory_mb
        if max_mb is None:
            return
        rss_mb = _get_resident_memory_mb()
        if rss_mb is not None and rss_mb > max_mb:
            logger.warning(
                "Resident memory %.2f MiB exceeded soft-cap %.2f MiB",
                rss_mb,
                max_mb,
            )
            if self._config.memory_limit_action == "abort":
                raise MemoryLimitExceededError(
                    f"Resident memory {rss_mb:.2f} MiB exceeded configured limit {max_mb:.2f} MiB"
                )

    async def _execute_single_case(
        self,
        case: EvaluationCase,
        adapter: TargetAdapter,
    ) -> ExecutionResult:
        timeout = self._config.case_timeout_seconds
        start = time.perf_counter()
        if timeout is None:
            return await adapter.execute(case)
        try:
            return await asyncio.wait_for(adapter.execute(case), timeout=timeout)
        except TimeoutError:
            elapsed = round_score(max(0.0, time.perf_counter() - start))
            return ExecutionResult(
                case_id=case.id,
                input=case.input,
                output=None,
                elapsed_seconds=elapsed,
                errors=[f"TimeoutError: case {case.id!r} exceeded timeout of {timeout}s"],
                system_version=adapter.system_version,
                model_id=adapter.model_id,
                config_fingerprint=adapter.config_fingerprint,
            )

    async def arun(
        self,
        dataset: DatasetEngine,
        adapter: TargetAdapter,
        metrics: Sequence[Metric],
        *,
        run_id: str | None = None,
    ) -> RunRecord:
        """Execute dataset cases asynchronously with bounded concurrency and fault isolation."""
        resolved_run_id = (
            run_id
            if run_id is not None
            else f"run-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}-{uuid.uuid4().hex[:8]}"
        )
        stream_info: list[DatasetStreamResult] = []
        case_iter = enumerate(
            dataset.iter_cases(
                max_cases=self._config.max_dataset_cases,
                on_complete=stream_info.append,
            )
        )
        iter_lock = asyncio.Lock()
        stop_event = asyncio.Event()
        completed_by_index: dict[int, CaseEvaluationRecord] = {}
        fatal_error: list[BaseException] = []

        async def _worker() -> None:
            while not stop_event.is_set():
                async with iter_lock:
                    if stop_event.is_set():
                        return
                    try:
                        index, case = next(case_iter)
                    except StopIteration:
                        return
                    except Exception as exc:
                        fatal_error.append(exc)
                        stop_event.set()
                        return

                self._check_memory_guardrail()
                execution = await self._execute_single_case(case, adapter)
                metric_results = _evaluate_metrics_safe(case, execution, metrics)
                persisted_execution = _truncate_execution_result(
                    execution, self._config.max_context_chars
                )
                record = CaseEvaluationRecord(
                    case_id=case.id,
                    mandatory=case.criteria.mandatory,
                    execution=persisted_execution,
                    metrics=metric_results,
                )
                completed_by_index[index] = record

                has_case_error = bool(persisted_execution.errors) or any(
                    m.status == MetricStatus.INCONCLUSIVE for m in metric_results.values()
                )
                if self._config.fail_fast and has_case_error:
                    fatal_error.append(
                        ExecutionError(
                            f"Execution aborted in fail_fast mode on case {case.id!r}: "
                            f"{persisted_execution.errors}"
                        )
                    )
                    stop_event.set()
                    return

        workers = [
            asyncio.create_task(_worker()) for _ in range(self._config.max_concurrency)
        ]
        try:
            await asyncio.gather(*workers)
        except Exception:
            for w in workers:
                w.cancel()
            raise

        if fatal_error:
            raise fatal_error[0]

        ordered_records = [completed_by_index[idx] for idx in sorted(completed_by_index)]
        meta = stream_info[0]
        aggregates, status_counts, mandatory_failed = _build_aggregates(metrics, ordered_records)
        metric_versions = {m.metadata.metric_id: m.metadata.metric_version for m in metrics}

        return RunRecord(
            run_id=resolved_run_id,
            timestamp=datetime.now(timezone.utc),
            package_version=_package_version(),
            dataset_id=meta.dataset_id,
            dataset_version=meta.dataset_version,
            dataset_fingerprint=meta.dataset_fingerprint,
            evaluated_case_count=meta.evaluated_case_count,
            dataset_capped=meta.dataset_capped,
            max_dataset_cases=meta.max_dataset_cases,
            system_version=adapter.system_version,
            model_id=adapter.model_id,
            config_fingerprint=adapter.config_fingerprint,
            metric_versions=metric_versions,
            seed=self._config.seed,
            aggregates=aggregates,
            status_counts=status_counts,
            mandatory_failed_case_ids=mandatory_failed,
            has_mandatory_failures=bool(mandatory_failed),
            case_results=ordered_records,
        )

    def run(
        self,
        dataset: DatasetEngine,
        adapter: TargetAdapter,
        metrics: Sequence[Metric],
        *,
        run_id: str | None = None,
    ) -> RunRecord:
        """Synchronously execute an evaluation run outside an active async event loop."""
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return asyncio.run(self.arun(dataset, adapter, metrics, run_id=run_id))
        raise ExecutionError(
            "EvaluationOrchestrator.run() cannot run inside an active event loop; "
            "await orchestrator.arun(...) instead"
        )

