"""Prompt-injection isolation, credential hygiene, and pre-network local-only security guards."""

from __future__ import annotations

import ipaddress
import os
import re
import secrets
from typing import Any
from urllib.parse import urlparse

from evalforge_maestro._canonical import canonical_json_str, scrub_secret_text
from evalforge_maestro.exceptions import LocalOnlyPolicyError
from evalforge_maestro.types import JudgeConfig

_VALID_TAG_RE = re.compile(r"^[a-z][a-z0-9_]*$")
_OLLAMA_PREFIXES = ("ollama/", "ollama_chat/")


def generate_nonce() -> str:
    """Return a cryptographically random 16-char hex delimiter nonce."""
    return secrets.token_hex(8)


def escape_untrusted_text(text: str, *, nonce: str | None = None) -> str:
    """Neutralize XML tag breakouts and accidental nonce collisions in untrusted payloads."""
    escaped = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    if nonce and nonce in escaped:
        escaped = escaped.replace(nonce, "[NONCE_REDACTED]")
    return escaped


def wrap_untrusted_block(tag_name: str, content: Any, *, nonce: str) -> str:
    """Wrap untrusted content in randomized nonce-tagged XML boundaries."""
    if not _VALID_TAG_RE.match(tag_name):
        raise ValueError(f"Invalid untrusted XML delimiter tag name: {tag_name!r}")
    if not nonce or not nonce.strip():
        raise ValueError("Delimiter nonce must be a non-empty string")
    raw = (
        content
        if isinstance(content, str)
        else canonical_json_str(content, pretty=True).rstrip("\n")
    )
    safe_body = escape_untrusted_text(raw, nonce=nonce)
    return f'<{tag_name} nonce="{nonce}">\n{safe_body}\n</{tag_name}>'


def is_loopback_host(hostname: str) -> bool:
    """Return True iff hostname resolves syntactically to localhost or a loopback IP."""
    normalized = hostname.strip().lower().rstrip(".")
    if normalized == "localhost":
        return True
    try:
        addr = ipaddress.ip_address(normalized)
    except ValueError:
        return False
    return addr.is_loopback


def validate_local_only_target(config: JudgeConfig) -> str | None:
    """Validate pre-network endpoint locality when local_only=True and mock_mode=False.

    Returns resolved target api_base URL (or config.api_base unchanged when allowed).
    Raises LocalOnlyPolicyError prior to any network import or socket operation.
    """
    if not config.local_only or config.mock_mode:
        return config.api_base

    model_lower = config.model.lower()
    if config.api_base is not None:
        target_url = config.api_base
    elif model_lower.startswith(_OLLAMA_PREFIXES):
        env_ollama_base = os.environ.get("OLLAMA_API_BASE", "").strip()
        target_url = env_ollama_base or "http://localhost:11434"
    else:
        raise LocalOnlyPolicyError(
            f"local_only policy blocked remote judge model {config.model!r}: "
            "configure mock_mode=True or an explicit loopback api_base "
            "(localhost, 127.0.0.1, ::1)."
        )

    parsed = urlparse(target_url)
    host = parsed.hostname
    if (
        parsed.scheme not in {"http", "https"}
        or not host
        or parsed.username is not None
        or parsed.password is not None
        or not is_loopback_host(host)
    ):
        raise LocalOnlyPolicyError(
            f"local_only policy blocked non-loopback endpoint {scrub_secret_text(target_url)!r}: "
            "only localhost, 127.0.0.1, and ::1 are permitted."
        )
    return target_url


def ensure_airgap_cost_map(*, local_only: bool) -> None:
    """Force LiteLLM offline bundled model cost-map lookup prior to importing litellm."""
    if local_only:
        os.environ["LITELLM_LOCAL_MODEL_COST_MAP"] = "True"
    else:
        os.environ.setdefault("LITELLM_LOCAL_MODEL_COST_MAP", "True")

"""Provider-independent LiteLLM completion wrapper, strict parser, and retry engine."""

from __future__ import annotations

import asyncio
import json
import logging
import re
from collections.abc import Awaitable, Callable
from typing import Any, NoReturn

from pydantic import ValidationError

from evalforge_maestro._canonical import FLOAT_EPSILON, round_score, scrub_secret_text
from evalforge_maestro.exceptions import JudgeError, LocalOnlyPolicyError, MissingExtraError
from evalforge_maestro.judges.security import (
    ensure_airgap_cost_map,
    validate_local_only_target,
)
from evalforge_maestro.types import (
    JudgeConfig,
    JudgeResponse,
    MetricMetadata,
    MetricResult,
    MetricStatus,
)

logger = logging.getLogger(__name__)

CompletionFn = Callable[..., Awaitable[str]]
_CODE_FENCE_RE = re.compile(
    r"^\s*```(?:json)?\s*\n?(.*?)\n?\s*```\s*$",
    re.DOTALL | re.IGNORECASE,
)


def _reject_json_constant(value: str) -> NoReturn:
    raise ValueError(f"Non-finite JSON constant is not allowed in JudgeResponse: {value!r}")


def parse_judge_response(raw_text: str) -> JudgeResponse:
    """Strictly parse raw judge output text into a bounded JudgeResponse schema."""
    if not isinstance(raw_text, str):
        raise ValueError(f"Judge output must be a string, got {type(raw_text).__name__}")
    cleaned = raw_text.strip()
    if not cleaned:
        raise ValueError("Judge output is empty")

    fenced = _CODE_FENCE_RE.match(cleaned)
    if fenced:
        cleaned = fenced.group(1).strip()

    try:
        parsed = json.loads(cleaned, parse_constant=_reject_json_constant)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Judge output is not valid JSON: {exc}") from exc

    if not isinstance(parsed, dict):
        raise ValueError(
            f"Judge JSON payload must be an object, got {type(parsed).__name__}"
        )

    try:
        return JudgeResponse.model_validate(parsed)
    except ValidationError as exc:
        raise ValueError(f"JudgeResponse validation failed: {exc}") from exc


def _resolve_litellm(*, local_only: bool) -> Any:
    """Enforce air-gap cost map setting and lazily import optional litellm package."""
    ensure_airgap_cost_map(local_only=local_only)
    try:
        import litellm
    except ImportError as exc:
        raise MissingExtraError(extra="judges", package="litellm") from exc

    litellm.telemetry = False
    litellm.suppress_debug_info = True
    return litellm


def _extract_choice_content(response: Any) -> str:
    choices = (
        response.get("choices")
        if isinstance(response, dict)
        else getattr(response, "choices", None)
    )
    if not choices:
        raise JudgeError("Judge provider returned empty choices list")
    first = choices[0]
    message = (
        first.get("message") if isinstance(first, dict) else getattr(first, "message", None)
    )
    if message is None:
        raise JudgeError("Judge provider choice missing message payload")
    content = (
        message.get("content")
        if isinstance(message, dict)
        else getattr(message, "content", None)
    )
    if not isinstance(content, str) or not content.strip():
        raise JudgeError("Judge provider returned empty message content")
    return content


async def invoke_live_completion(
    messages: list[dict[str, str]],
    *,
    config: JudgeConfig,
    api_key: str | None = None,
    completion_fn: CompletionFn | None = None,
) -> str:
    """Execute one model completion under pre-network local_only and secret hygiene."""
    resolved_api_base = validate_local_only_target(config)

    if completion_fn is not None:
        return await completion_fn(
            model=config.model,
            messages=messages,
            temperature=config.temperature,
            api_base=resolved_api_base,
            timeout=config.timeout_seconds,
            seed=config.seed,
        )

    litellm = _resolve_litellm(local_only=config.local_only)
    call_kwargs: dict[str, Any] = {
        "model": config.model,
        "messages": messages,
        "temperature": config.temperature,
        "timeout": config.timeout_seconds,
        "response_format": {"type": "json_object"},
    }
    if resolved_api_base is not None:
        call_kwargs["api_base"] = resolved_api_base
    if config.seed is not None:
        call_kwargs["seed"] = config.seed
    if api_key is not None and api_key.strip():
        call_kwargs["api_key"] = api_key
    for key, val in config.extra_params.items():
        if key not in call_kwargs:
            call_kwargs[key] = val

    try:
        response = await litellm.acompletion(**call_kwargs)
    except Exception as exc:
        raise JudgeError(scrub_secret_text(f"Provider call failed: {type(exc).__name__}: {exc}")) from exc
    return _extract_choice_content(response)


async def evaluate_with_retries(
    call_once: Callable[[int], Awaitable[str]],
    *,
    config: JudgeConfig,
    effective_threshold: float,
    metadata: MetricMetadata,
    config_snapshot: dict[str, Any],
    allow_retries: bool = True,
) -> MetricResult:
    """Invoke judge evaluation with bounded retries and mandatory INCONCLUSIVE fallback."""
    max_attempts = (config.max_retries + 1) if allow_retries else 1
    last_error = "No attempts executed"

    for attempt in range(max_attempts):
        try:
            raw_text = await asyncio.wait_for(
                call_once(attempt),
                timeout=config.timeout_seconds,
            )
            parsed = parse_judge_response(raw_text)
        except (LocalOnlyPolicyError, MissingExtraError):
            raise
        except Exception as exc:
            last_error = scrub_secret_text(f"{type(exc).__name__}: {exc}")
            logger.debug(
                "Judge %s attempt %d/%d failed: %s",
                metadata.metric_id,
                attempt + 1,
                max_attempts,
                last_error,
            )
            if attempt + 1 < max_attempts:
                delay = 0.0 if config.mock_mode else config.retry_backoff_seconds * (2**attempt)
                if delay > 0.0:
                    await asyncio.sleep(delay)
            continue

        score = round_score(parsed.score)
        passed = score >= effective_threshold - FLOAT_EPSILON
        status = MetricStatus.PASS if passed else MetricStatus.FAIL
        evidence = list(parsed.supported_claims) + [
            f"UNSUPPORTED: {claim}" for claim in parsed.unsupported_claims
        ]
        anomaly_flags: list[str] = []
        if passed and parsed.unsupported_claims:
            anomaly_flags.append("unsupported_claims_present")

        return MetricResult(
            metric_id=metadata.metric_id,
            metric_version=metadata.metric_version,
            score=score,
            status=status,
            label=parsed.verdict or ("pass" if passed else "fail"),
            explanation=scrub_secret_text(parsed.rationale),
            evidence=evidence,
            anomaly_flags=anomaly_flags,
            config_snapshot=config_snapshot,
        )

    return MetricResult(
        metric_id=metadata.metric_id,
        metric_version=metadata.metric_version,
        score=None,
        status=MetricStatus.INCONCLUSIVE,
        explanation=f"INCONCLUSIVE after {max_attempts} attempt(s): {last_error}",
        config_snapshot=config_snapshot,
    )

