# Guard concurrent worker threads against ChromaDB SharedSystemClient and
# docpipe_maestro <= 0.3 lazy registry cold-start races on process-global state.
_DOCPIPE_RETRIEVE_LOCK = threading.Lock()


def _accepts_kwarg(fn: Callable[..., Any], name: str) -> bool:
    try:
        params = inspect.signature(fn).parameters.values()
    except (TypeError, ValueError):
        return False
    return any(p.kind == inspect.Parameter.VAR_KEYWORD or p.name == name for p in params)


def _wrap_sync_retrieve(fn: Callable[..., Any]) -> Callable[..., Any]:
    if inspect.iscoroutinefunction(fn):
        return fn

    @functools.wraps(fn)
    def _locked_retrieve(*args: Any, **kwargs: Any) -> Any:
        with _DOCPIPE_RETRIEVE_LOCK:
            return fn(*args, **kwargs)

    return _locked_retrieve

