def _cap_sequence_budget(items: list[Any], max_chars: int) -> tuple[list[Any], bool]:
    capped = list(items)
    changed = False
    while (
        len(capped) > 1
        and len(canonical_json_str([entry.model_dump(mode="json") for entry in capped])) > max_chars
    ):
        capped.pop()
        changed = True
    return capped, changed

