            baseline_name=baseline_alias,
            policy=resolved.gate,
        )
        gate_result = QualityGate(resolved.gate).evaluate_cohort(
            candidate_runs,
            comparison=comparison,
        )

    doc = build_comparison_report(
        comparison,
        candidate_run=candidate_runs[-1],
